<script setup lang="ts">
import { computed,ref,onMounted,onUnmounted } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import PageHeading from '../components/PageHeading.vue'
import CheckboxDropdown from '../components/CheckboxDropdown.vue'
import { api,bootstrap,notify } from '../composables/api'
import { useCollaborationAction } from '../composables/collaboration'
import type { AlertConfiguration,AlertRuleDefinition,AlertRuleItem } from '../types'
const config=ref<AlertConfiguration|null>(null),draft=ref<AlertRuleDefinition|null>(null),editing=ref<AlertRuleItem|null>(null),baseline=ref(''),error=ref(''),loading=ref(false),saving=ref(false),preview=ref<{text:string;detail:string}|null>(null),example=ref(''),perform=useCollaborationAction()
const dirty=computed(()=>!!draft.value&&baseline.value!==JSON.stringify(draft.value)),summary=computed(()=>draft.value&&config.value?draft.value.events.map(e=>config.value!.events[e]).join(', ')+' in '+draft.value.conditions.environments.join(', ')+' → '+draft.value.connections.length+' destination'+(draft.value.connections.length===1?'':'s')+'. Cooldown: '+Math.round(draft.value.cooldown_seconds/60)+' minutes.':'')
const primary=['error.created','error.regressed','error.threshold_reached']
function confirmLeave(){return !dirty.value||window.confirm('Discard this unsaved rule draft?')}
onBeforeRouteLeave(confirmLeave);const unload=(e:BeforeUnloadEvent)=>{if(dirty.value){e.preventDefault();e.returnValue=''}};onMounted(()=>{window.addEventListener('beforeunload',unload);if(bootstrap.value?.capabilities.manage)load()});onUnmounted(()=>window.removeEventListener('beforeunload',unload))
async function load(){loading.value=true;try{config.value=await api<AlertConfiguration>('/alerting');if(!draft.value)choose(null)}catch(e){error.value=e instanceof Error?e.message:'Rules unavailable.'}finally{loading.value=false}}
function choose(rule:AlertRuleItem|null){if(!confirmLeave())return;editing.value=rule;draft.value=JSON.parse(JSON.stringify(rule?{name:rule.name,enabled:rule.enabled,events:rule.events,conditions:rule.conditions,connections:rule.connections,threshold_count:rule.threshold_count,window_seconds:rule.window_seconds,cooldown_seconds:rule.cooldown_seconds}:config.value!.starter));baseline.value=JSON.stringify(draft.value);preview.value=null;error.value=''}
function duplicate(){if(!draft.value||!confirmLeave())return;draft.value={...JSON.parse(JSON.stringify(draft.value)),name:draft.value.name.slice(0,110)+' copy',enabled:false};editing.value=null;baseline.value=''}
async function save(){if(!draft.value)return;saving.value=true;error.value='';try{const result=await perform<{id:string}>('/alerting/rules'+(editing.value?'/'+editing.value.id:''),editing.value?'PATCH':'POST',{...draft.value,...(editing.value?{version:editing.value.version}:{})});baseline.value=JSON.stringify(draft.value);notify('Rule saved. Existing pending work is revalidated before sending.');config.value=await api<AlertConfiguration>('/alerting');choose(config.value.rules.find(r=>r.id===result.id)??null)}catch(e){error.value=e instanceof Error?e.message:'Rule could not be saved.'}finally{saving.value=false}}
async function remove(){if(!editing.value||!window.confirm('Delete this rule? Its pending support is removed; history remains.'))return;saving.value=true;try{await perform('/alerting/rules/'+editing.value.id,'DELETE',{version:editing.value.version});draft.value=null;editing.value=null;baseline.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Delete failed.'}finally{saving.value=false}}
async function showPreview(){if(!draft.value)return;error.value='';try{preview.value=await api('/alerting/preview','POST',{definition:draft.value,...(example.value?{issue:example.value}:{})})}catch(e){error.value=e instanceof Error?e.message:'Preview unavailable.'}}
async function reload(){if(!confirmLeave())return;const id=editing.value?.id;draft.value=null;baseline.value='';await load();if(id&&config.value)choose(config.value.rules.find(r=>r.id===id)??null)}
</script>
<template><PageHeading title="Alert rules" subtitle="Choose when to notify and where each alert goes."><RouterLink to="/alerts/history" class="button">Delivery history</RouterLink></PageHeading><div v-if="!bootstrap?.features.alerts" class="notice warning">Publish and run the alerting migration to enable this module.</div><div v-else-if="!bootstrap?.capabilities.manage" class="notice neutral"><p>Administrators configure rules and recipients. You can inspect sanitized delivery history.</p></div><template v-else><p v-if="loading" role="status">Loading alert configuration…</p><div v-if="error" class="notice danger" role="alert">{{error}}<button class="button" @click="reload">Reload configuration</button></div><nav v-if="config" class="rule-switcher" aria-label="Alert rules"><button class="button" :disabled="saving" @click="choose(null)">New rule</button><button v-for="r in config.rules" :key="r.id" class="button" :class="{selected:editing?.id===r.id}" :disabled="saving" @click="choose(r)">{{r.name}} <small>{{r.enabled?'Enabled':'Draft'}}</small></button></nav><div v-if="draft&&config" class="rule-layout"><form class="panel rule-form" @submit.prevent="save"><div class="section-heading"><h2>{{draft.name||'New alert rule'}}</h2><span class="badge">{{draft.enabled?'Enabled after save':'Draft'}}</span></div><label class="field">Rule name<input v-model="draft.name" required maxlength="120" :disabled="saving"></label><fieldset><legend>When these events occur</legend><label v-for="event in primary" :key="event" class="checkbox-row"><input v-model="draft.events" type="checkbox" :value="event" :disabled="saving">{{config.events[event]}}</label></fieldset><div v-if="draft.events.includes('error.threshold_reached')" class="threshold-fields"><label class="field">Crossing count<input v-model.number="draft.threshold_count" type="number" min="1" required></label><label class="field">Fixed UTC window<select v-model.number="draft.window_seconds" required><option :value="300">5 minutes</option><option :value="900">15 minutes</option><option :value="3600">1 hour</option></select></label><p class="help">One crossing per rule revision/error/fixed UTC window. Historical replay does not trigger notifications.</p></div><details class="activity-rule-events"><summary>Activity notifications</summary><label v-for="(label,event) in config.events" v-show="!primary.includes(event)" :key="event" class="checkbox-row"><input v-model="draft.events" type="checkbox" :value="event" :disabled="event==='assignment.changed'&&!bootstrap?.features.assignments">{{label}}<small v-if="event==='assignment.changed'&&!bootstrap?.features.assignments">Requires host directory</small></label><p class="help">Each activity type has its own per-error/destination cooldown scope and action identity. A resolved notice remains meaningful while resolved.</p></details><CheckboxDropdown v-model="draft.conditions.environments" label="Environment" :options="config.allowed_environments" :disabled="saving"/><details class="rule-conditions"><summary>Optional class, origin and tag conditions</summary><label class="field">Exact exception class<input v-model="draft.conditions.class" placeholder="Any exception class"></label><label class="field">Origin<select v-model="draft.conditions.origin"><option :value="null">Any origin</option><option v-for="origin in ['web','job','command','unknown']" :key="origin">{{origin}}</option></select></label><label v-if="config.allowed_tags.length" class="field">Permitted tag (key:value)<input v-model="draft.conditions.tag"><small>{{config.allowed_tags.join(', ')}}</small></label><p class="help">Thresholds count matching retained projections, not global buckets. Activity origin/tag conditions use the latest captured occurrence context.</p></details><fieldset><legend>Send to</legend><label v-for="c in config.connections" :key="c.id" class="checkbox-row"><input v-model="draft.connections" type="checkbox" :value="c.id" :disabled="!c.enabled||c.disconnected">{{c.provider}} · {{c.name}} · {{c.email??c.display}} <small v-if="!c.enabled||c.disconnected">Unavailable</small></label><p v-if="!config.connections.length" class="help">No recipients configured.</p><p class="help">Overlapping rules share the canonical destination cooldown.</p><RouterLink to="/integrations" class="text-link">Manage all integrations</RouterLink></fieldset><label class="field">Per-error, per-destination cooldown<select v-model.number="draft.cooldown_seconds"><option :value="0">No cooldown</option><option v-for="minutes in [5,15,30,60,240,1440].filter(m=>m*60<=config!.max_cooldown_seconds)" :key="minutes" :value="minutes*60">{{minutes}} minutes</option></select></label><label class="checkbox-row"><input v-model="draft.enabled" type="checkbox">Enable after saving</label><p v-if="!config.enabled" class="field-error">Delivery is disabled by deployment policy.</p><div class="inline-actions spacing"><button class="button primary" :disabled="saving">{{saving?'Saving…':'Save rule'}}</button><button type="button" class="button" :disabled="saving" @click="showPreview">Preview notification</button><button v-if="editing" type="button" class="button" :disabled="saving" @click="duplicate">Duplicate</button><button v-if="editing" type="button" class="text-link danger-link" :disabled="saving" @click="remove">Delete rule</button></div><span v-if="dirty" class="unsaved">Unsaved changes</span></form><aside class="rule-rail"><section class="panel"><h2>Rule summary</h2><p>{{summary}}</p><p class="help">Overlapping rules coalesce by canonical recipient. New errors/regressions take priority over a simultaneous threshold.</p></section><section class="panel notification-preview"><h2>Notification preview</h2><label class="field">Example error UUID (optional)<input v-model="example" placeholder="Use synthetic example"></label><pre v-if="preview">{{preview.text}}</pre><p v-else class="help">Preview a sanitized example using the current draft. Nothing is sent.</p><p class="help">Email can include privacy-permitted route metadata and bounded stack frames. Request payloads, SQL, user identities and note text are excluded.</p><RouterLink to="/settings/email" class="button">Send synthetic test</RouterLink></section></aside></div></template></template>
